package internalreleaseimage

import (
	corev1 "k8s.io/api/core/v1"

	configv1 "github.com/openshift/api/config/v1"
	mcfgv1 "github.com/openshift/api/machineconfiguration/v1"
)

// RunInternalReleaseImageBootstrap generates the MachineConfig objects for InternalReleaseImage that would have been generated by syncInternalReleaseImage.
func RunInternalReleaseImageBootstrap(iriSecret, iriRegistryCredentialsSecret *corev1.Secret, cconfig *mcfgv1.ControllerConfig, tlsProfile *configv1.TLSSecurityProfile) ([]*mcfgv1.MachineConfig, error) {
	configs := []*mcfgv1.MachineConfig{}

	for _, role := range SupportedRoles {
		r := NewRendererByRole(role, iriSecret, iriRegistryCredentialsSecret, cconfig, tlsProfile)
		mc, err := r.createEmptyMachineConfig()
		if err != nil {
			return nil, err
		}
		err = r.RenderAndSetIgnition(mc)
		if err != nil {
			return nil, err
		}
		configs = append(configs, mc)
	}

	return configs, nil
}
